typedef struct { int start, end, next; char type; } Tok;
typedef struct { const char *s; Tok t[8192]; int n; } Parser;
static int parse(Parser *p){
 jsmntok_t raw[8192];jsmn_parser jp;jsmn_init(&jp);int n=jsmn_parse(&jp,p->s,strlen(p->s),raw,8192);if(n<=0)return 0;p->n=n;
 for(int i=0;i<n;i++){int k=i+1;Tok*t=&p->t[k];t->type=raw[i].type==JSMN_OBJECT?'{':raw[i].type==JSMN_ARRAY?'[':raw[i].type==JSMN_STRING?'s':'v';t->start=raw[i].start-(t->type=='s');t->end=raw[i].end+(t->type=='s');int j=i+1;while(j<n&&raw[j].start<raw[i].end)j++;t->next=j+1;}
 return 1;
}
static int eq(Parser*p,int i,const char*s){return i>0&&p->t[i].type=='s'&&(int)strlen(s)==p->t[i].end-p->t[i].start-2&&!memcmp(p->s+p->t[i].start+1,s,strlen(s));}
static int field(Parser*p,int obj,const char*key){if(!obj||p->t[obj].type!='{')return 0;for(int i=obj+1;i<p->t[obj].next;){int k=i,v=i+1;if(eq(p,k,key))return v;i=p->t[v].next;}return 0;}
static char *str(Parser*p,int i){if(!i||p->t[i].type!='s')return NULL;int n=p->t[i].end-p->t[i].start-2;char *r=malloc((size_t)n+1);if(!r)return NULL;int j=0;for(int x=p->t[i].start+1;x<p->t[i].end-1;x++){char c=p->s[x];if(c=='\\'&&x+1<p->t[i].end-1){c=p->s[++x];if(c=='n')c='\n';else if(c=='r')c='\r';else if(c=='t')c='\t';}r[j++]=c;}r[j]=0;return r;}
static long num(Parser*p,int i,long d){if(!i)return d;int start=p->t[i].start+(p->t[i].type=='s'),end=p->t[i].end-(p->t[i].type=='s');int n=end-start;if(n<=0||n>=64)return d;char b[64];memcpy(b,p->s+start,(size_t)n);b[n]=0;char*e;long v=strtol(b,&e,0);return *e?d:v;}
static bool boolean(Parser*p,int i,bool d){if(!i)return d;if(p->t[i].type=='v'){int n=p->t[i].end-p->t[i].start;if(n==4&&!memcmp(p->s+p->t[i].start,"true",4))return true;if(n==5&&!memcmp(p->s+p->t[i].start,"false",5))return false;}return d;}
static long address_value(Parser*p,CPC*c,int i){if(!i)return-1;if(p->t[i].type!='s')return num(p,i,-1);char*expr=str(p,i);if(!expr)return-1;int32_t v=-1;char error[128];bool ok=dbg_eval(c,expr,&v,error,sizeof error);free(expr);return ok?v:-1;}
static const char B64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static unsigned char *unb64(const char*s,size_t*out){size_t n=strlen(s);if(n%4)return NULL;size_t pad=n&&s[n-1]=='='?1:0;if(n>1&&s[n-2]=='=')pad++;size_t cap=n/4*3-pad;unsigned char*b=malloc(cap?cap:1);if(!b)return NULL;size_t j=0;for(size_t i=0;i<n;i+=4){unsigned v=0;for(int k=0;k<4;k++){char ch=s[i+k];if(ch=='='){if(i+4!=n||k<2||(k==2&&s[i+3]!='=')){free(b);return NULL;}v<<=6;}else{const char*q=strchr(B64,ch);if(!q||i+k>=n-pad){free(b);return NULL;}v=(v<<6)|(unsigned)(q-B64);}}if(j<cap)b[j++]=(unsigned char)(v>>16);if(j<cap)b[j++]=(unsigned char)(v>>8);if(j<cap)b[j++]=(unsigned char)v;}*out=j;return b;}
static char *b64(const unsigned char*b,size_t n){size_t cap=((n+2)/3)*4;char*r=malloc(cap+1);if(!r)return NULL;size_t j=0;for(size_t i=0;i<n;i+=3){unsigned v=(unsigned)b[i]<<16;if(i+1<n)v|=(unsigned)b[i+1]<<8;if(i+2<n)v|=b[i+2];r[j++]=B64[(v>>18)&63];r[j++]=B64[(v>>12)&63];r[j++]=i+1<n?B64[(v>>6)&63]:'=';r[j++]=i+2<n?B64[v&63]:'=';}r[j]=0;return r;}
struct CPCApiSession{CPC*c;int boot_target;int boot_configured;bool rom_os,rom_basic,rom_amsdos;};
CPCApiSession*cpc_api_create(void){CPCApiSession*s=calloc(1,sizeof*s);if(!s)return NULL;s->c=cpc_create(CPC_MODEL_6128);if(!s->c){free(s);return NULL;}return s;}
void cpc_api_destroy(CPCApiSession*s){if(s){if(s->c){for(int i=0;i<4;i++)dsk_free(fdc_disc(s->c->fdc,i));cpc_destroy(s->c);}free(s);}}
static char* response(const char*id,const char*result,const char*error){size_t n=strlen(id)+strlen(result?result:"null")+(error?strlen(error)+80:48);char*r=malloc(n);if(!r)return NULL;if(error){int code=!strcmp(error,"invalid JSON")?-32700:!strcmp(error,"method not found")?-32601:!strcmp(error,"missing method")?-32600:-32000;snprintf(r,n,"{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":%d,\"message\":\"%s\"}}",id,code,error);}else snprintf(r,n,"{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":%s}",id,result?result:"null");return r;}
char*cpc_api_dispatch(CPCApiSession*s,const char*request){if(!s||!request)return NULL;Parser p={.s=request};int root=parse(&p);if(!root||p.t[root].type!='{')return response("null",NULL,"invalid JSON");int version=field(&p,root,"jsonrpc");if(!eq(&p,version,"2.0"))return response("null",NULL,"invalid JSON-RPC version");int id=field(&p,root,"id");char idbuf[64]="null";if(id){int n=p.t[id].end-p.t[id].start;if(n<63){memcpy(idbuf,request+p.t[id].start,(size_t)n);idbuf[n]=0;}}
 char*m=str(&p,field(&p,root,"method"));int a=field(&p,root,"params");CPC*c=s->c;char out[512];const char*err=NULL;
 if(!m)err="missing method";
 else if(!strcmp(m,"session.capabilities")){snprintf(out,sizeof out,"{\"api_version\":\"1.0\",\"machine\":\"CPC 6128\",\"roms_loaded\":{\"os\":%s,\"basic\":%s,\"amsdos\":%s},\"capabilities\":[\"run\",\"headless\",\"capture\",\"memory\"],\"transports\":[\"stdio\"]}",s->rom_os?"true":"false",s->rom_basic?"true":"false",s->rom_amsdos?"true":"false");}
 else if(!strcmp(m,"rom.load")){char*role=str(&p,field(&p,a,"role"));char*payload=str(&p,field(&p,a,"data_base64"));size_t n=0;unsigned char*b=payload?unb64(payload,&n):NULL;int slot=-99;bool*loaded=NULL;if(role&&!strcmp(role,"os")){slot=-1;loaded=&s->rom_os;}else if(role&&!strcmp(role,"basic")){slot=0;loaded=&s->rom_basic;}else if(role&&!strcmp(role,"amsdos")){slot=7;loaded=&s->rom_amsdos;}if(!loaded)err="role must be os, basic, or amsdos";else if(!b||n!=16384)err="ROM must contain exactly 16384 bytes";else if(!cpc_load_rom(c,slot,b,n))err="ROM load failed";else{*loaded=true;strcpy(out,"true");}free(role);free(payload);free(b);}
 else if(!strcmp(m,"machine.reset")){cpc_reset(c,true);strcpy(out,"true");}
 else if(!strcmp(m,"run.frames")){long n=num(&p,field(&p,a,"count"),1);if(n<0||n>1000000)err="count out of range";else{for(long i=0;i<n;i++)cpc_run_frame(c);snprintf(out,sizeof out,"{\"frames\":%" PRIu64 ",\"pc\":%u}",c->frames,c->z80.pc);}}
 else if(!strcmp(m,"run.instructions")||!strcmp(m,"run.nops")){long count=num(&p,field(&p,a,"count"),1);if(count<0||count>100000000)err="count out of range";else{long steps=0,nops=0;while((!strcmp(m,"run.instructions")&&steps<count)||(!strcmp(m,"run.nops")&&nops<count)){int n=cpc_step(c);if(n<=0)n=1;steps++;nops+=n;}snprintf(out,sizeof out,"{\"requested\":%ld,\"executed_instructions\":%ld,\"advanced_nops\":%ld,\"pc\":%u,\"t_states_aligned\":%" PRIu64 "}",count,steps,nops,c->z80.pc,c->t_counter*4);}}
 else if(!strcmp(m,"cpu.registers")){snprintf(out,sizeof out,"{\"pc\":%u,\"sp\":%u,\"af\":%u,\"bc\":%u,\"de\":%u,\"hl\":%u,\"ix\":%u,\"iy\":%u,\"af_alt\":%u,\"bc_alt\":%u,\"de_alt\":%u,\"hl_alt\":%u,\"i\":%u,\"r\":%u,\"im\":%u,\"iff1\":%s,\"iff2\":%s,\"halted\":%s,\"frames\":%" PRIu64 ",\"nops\":%" PRIu64 "}",c->z80.pc,c->z80.sp.w,c->z80.af.w,c->z80.bc.w,c->z80.de.w,c->z80.hl.w,c->z80.ix.w,c->z80.iy.w,c->z80.af2.w,c->z80.bc2.w,c->z80.de2.w,c->z80.hl2.w,c->z80.i,c->z80.r,c->z80.im,c->z80.iff1?"true":"false",c->z80.iff2?"true":"false",c->z80.halted?"true":"false",c->frames,c->t_counter);}
 else if(!strcmp(m,"mem.read")){long addr=address_value(&p,c,field(&p,a,"address")),len=num(&p,field(&p,a,"length"),1);if(addr<0||addr>65535||len<1||len>4096||addr+len>65536)err="invalid memory range or symbol";else{size_t cap=(size_t)len*2+48;char*r=malloc(cap);if(!r)err="out of memory";else{int z=snprintf(r,cap,"{\"address\":%ld,\"hex\":\"",addr);for(long i=0;i<len;i++)z+=snprintf(r+z,cap-(size_t)z,"%02x",cpc_peek(c,(uint16_t)(addr+i)));snprintf(r+z,cap-(size_t)z,"\"}");char*ret=response(idbuf,r,NULL);free(r);free(m);return ret;}}}
 else if(!strcmp(m,"mem.write")){long addr=address_value(&p,c,field(&p,a,"address")),v=num(&p,field(&p,a,"value"),-1);if(addr<0||addr>65535||v<0||v>255)err="invalid address or byte";else{cpc_poke(c,(uint16_t)addr,(uint8_t)v);strcpy(out,"true");}}
 else if(!strcmp(m,"state.hash")){snprintf(out,sizeof out,"{\"hash\":\"%016" PRIx64 "\"}",cpc_state_hash(c));}
 else if(!strcmp(m,"state.save")){CPCState*st=cpc_state_save(c);if(!st)err="state save failed";else{size_t n=0;const uint8_t*b=cpc_state_bytes(st,&n);char*data=b64(b,n);size_t cap=strlen(data)+64;char*r=malloc(cap);snprintf(r,cap,"{\"data_base64\":\"%s\"}",data);char*ret=response(idbuf,r,NULL);free(r);free(data);cpc_state_free(st);free(m);return ret;}}
 else if(!strcmp(m,"state.restore")){char*payload=str(&p,field(&p,a,"data_base64"));size_t n=0;unsigned char*b=payload?unb64(payload,&n):NULL;CPCState*st=b?cpc_state_from_bytes(b,n):NULL;if(!st)err="invalid state image";else{unsigned hazards=0;if(!cpc_state_restore(c,st,&hazards))err="state restore failed";else snprintf(out,sizeof out,"{\"restored\":true,\"hazards\":%u}",hazards);}cpc_state_free(st);free(payload);free(b);}
 else if(!strcmp(m,"snapshot.load")||!strcmp(m,"disc.load")){char*payload=str(&p,field(&p,a,"data_base64"));long drive=num(&p,field(&p,a,"drive"),0);size_t n=0;unsigned char*b=payload?unb64(payload,&n):NULL;if(!b)err="missing or invalid data_base64";else if(!strcmp(m,"snapshot.load")){if(!cpc_snapshot_load(c,b,n))err="snapshot load failed";else strcpy(out,"true");}else if(drive<0||drive>1)err="drive must be 0 or 1";else{CPCDisc*d=dsk_load(b,n,"<api>");if(!d)err="invalid DSK";else{CPCDisc*old=fdc_disc(c->fdc,(int)drive);fdc_insert(c->fdc,(int)drive,d);dsk_free(old);strcpy(out,"true");}}free(payload);free(b);}
 else if(!strcmp(m,"snapshot.save")){long version=num(&p,field(&p,a,"version"),3);size_t n=0;uint8_t*b=cpc_snapshot_save(c,(int)version,0,true,&n);if(!b)err="snapshot save failed";else{char*data=b64(b,n);size_t cap=strlen(data)+64;char*r=malloc(cap);snprintf(r,cap,"{\"data_base64\":\"%s\"}",data);char*ret=response(idbuf,r,NULL);free(b);free(data);free(r);free(m);return ret;}}
 else if(!strcmp(m,"input.text")){char*t=str(&p,field(&p,a,"text"));if(!t)err="missing text";else{cpc_autotype(c,t);free(t);strcpy(out,"true");}}
 else if(!strcmp(m,"input.matrix")){long row=num(&p,field(&p,a,"row"),-1),mask=num(&p,field(&p,a,"mask"),-1);bool pressed=boolean(&p,field(&p,a,"pressed"),false);if(row<0||row>9||mask<0||mask>255||mask==255)err="row must be 0..9 and mask must select at least one key";else{for(int bit=0;bit<8;bit++)if(!(mask&(1<<bit))){if(pressed)c->kbd[row]&=(uint8_t)~(1<<bit);else c->kbd[row]|=(uint8_t)(1<<bit);}strcpy(out,"true");}}
 else if(!strcmp(m,"symbols.load")){char*payload=str(&p,field(&p,a,"data_base64"));size_t n=0;unsigned char*b=payload?unb64(payload,&n):NULL;if(!b)err="missing or invalid symbols data_base64";else{Debugger*d=dbg_attach(c);d->hist_on=false;d->active=false;int count=dbg_symbols_parse(c,(char*)b,n);if(count<0)err="symbol parsing failed";else snprintf(out,sizeof out,"{\"loaded\":%d}",count);}free(payload);free(b);}
 else if(!strcmp(m,"boot_ready.configure")){s->boot_target=(int)num(&p,field(&p,a,"address"),-1);s->boot_configured=s->boot_target>=0&&s->boot_target<=65535;snprintf(out,sizeof out,"{\"configured\":%s,\"address\":%d}",s->boot_configured?"true":"false",s->boot_target);}
 else if(!strcmp(m,"boot_ready.status")){bool drained=!cpc_autotype_active(c);for(int row=0;row<16;row++)if(c->kbd[row]!=0xFF)drained=false;snprintf(out,sizeof out,"{\"ready\":%s,\"pc\":%u,\"keyboard_drained\":%s,\"target\":%d}",s->boot_configured&&c->z80.pc==s->boot_target&&drained?"true":"false",c->z80.pc,drained?"true":"false",s->boot_target);}
 else if(!strcmp(m,"screen.capture")){size_t pixels=(size_t)CPC_SCREEN_W*CPC_SCREEN_H,n=pixels*4;const uint32_t*frame=cpc_frame(c);if(!frame)frame=c->frame;uint8_t*rgba=malloc(n);if(!rgba)err="out of memory";else{for(size_t i=0;i<pixels;i++){uint32_t px=frame[i];rgba[i*4]=(uint8_t)(px>>16);rgba[i*4+1]=(uint8_t)(px>>8);rgba[i*4+2]=(uint8_t)px;rgba[i*4+3]=(uint8_t)(px>>24);}char*data=b64(rgba,n);size_t cap=strlen(data)+160;char*r=malloc(cap);snprintf(r,cap,"{\"frame\":%" PRIu64 ",\"width\":%d,\"height\":%d,\"format\":\"rgba8\",\"data_base64\":\"%s\"}",c->frames,CPC_SCREEN_W,CPC_SCREEN_H,data);char*ret=response(idbuf,r,NULL);free(r);free(data);free(rgba);free(m);return ret;}}
 else if(!strcmp(m,"run.reset_tstates")){c->t_counter=0;strcpy(out,"true");}
 else err="method not found";
 char*ret=response(idbuf,out,err);free(m);return ret;
}
